package net.civeira.phylax.feature.observe.observedalertrule.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRule;
import net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject.CooldownMinutesVO;

class CooldownMinutesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of cooldown minutes of observed alert rule")
  void test_cooldown_minutes_value_holder_assign_plain_value() {
    Object holder = new Object();
    CooldownMinutesValueHolder<Object> value = new CooldownMinutesValueHolder<>(holder);
    Assertions.assertSame(holder, value.cooldownMinutes(1), "Setters must return the holder");
    Assertions.assertTrue(value.getCooldownMinutesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getCooldownMinutes().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of cooldown minutes of observed alert rule")
  void test_cooldown_minutes_value_holder_assign_value_object() {
    Object holder = new Object();
    CooldownMinutesValueHolder<Object> value = new CooldownMinutesValueHolder<>(holder);
    CooldownMinutesVO vo = CooldownMinutesVO.from(1);
    Assertions.assertFalse(value.getCooldownMinutesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.cooldownMinutes(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getCooldownMinutesValue().orElseThrow());
    Assertions.assertSame(holder, value.cooldownMinutes(Optional.empty()));
    Assertions.assertFalse(value.getCooldownMinutesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.cooldownMinutes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getCooldownMinutesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of cooldown minutes of observed alert rule against the original")
  void test_cooldown_minutes_value_holder_read() {
    Object holder = new Object();
    CooldownMinutesValueHolder<Object> value = new CooldownMinutesValueHolder<>(holder);
    CooldownMinutesVO vo = CooldownMinutesVO.from(1);
    CooldownMinutesVO other = CooldownMinutesVO.from(1);
    ObservedAlertRule original = Mockito.mock(ObservedAlertRule.class);
    Mockito.when(original.getCooldownMinutesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readCooldownMinutes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readCooldownMinutes(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.cooldownMinutes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readCooldownMinutes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readCooldownMinutes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of cooldown minutes of observed alert rule")
  void test_cooldown_minutes_value_holder_unset() {
    Object holder = new Object();
    CooldownMinutesValueHolder<Object> value = new CooldownMinutesValueHolder<>(holder);
    CooldownMinutesVO vo = CooldownMinutesVO.from(1);
    value.cooldownMinutes(vo);
    Assertions.assertSame(holder, value.unsetCooldownMinutesIfMatches("cooldownMinutes_other"));
    Assertions.assertTrue(value.getCooldownMinutesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetCooldownMinutesIfMatches("cooldownMinutes"));
    Assertions.assertFalse(value.getCooldownMinutesValue().isPresent(),
        "The field name must clear the value");
    value.cooldownMinutes(vo);
    Assertions.assertSame(holder, value.unsetCooldownMinutes());
    Assertions.assertFalse(value.getCooldownMinutesValue().isPresent(),
        "Unset must clear the value");
  }
}
